sys_transform_map.script:
// Add your code here
	(function runTransformScript(source, target, map, log, isUpdate) {

    try {

        // ✅ Copy values manually if needed
        target.case_number = source.number;
        target.description = source.description;

        // ✅ Example: convert priority
        if (source.priority == '1') {
            target.priority = 'High';
        }

        // ✅ Log success
        log.info("Record transformed for case: " + source.number);

    } catch (ex) {
        log.error("Transform error: " + ex.message);
    }

})(source, target, map, log, action === "update");
